from collections import deque
s=['00011100','01110100','01000100','01000100','01000100','01111100','00000000','00000000']
# components of ones and bounding boxes
G=[list(map(int,r)) for r in s]; seen=set()
for r in range(8):
 for c in range(8):
  if G[r][c] and (r,c) not in seen:
   q=[(r,c)]; seen.add((r,c)); comp=[]
   for x,y in q:
    comp.append((x,y))
    for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     if 0<=a<8 and 0<=b<8 and G[a][b] and (a,b) not in seen: seen.add((a,b));q.append((a,b))
   print(min(x for x,y in comp),max(x for x,y in comp),min(y for x,y in comp),max(y for x,y in comp),len(comp))
