 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL-openclaw-luna6-low-ws0/frozen/held-out-2/play/users/u076/system/state/workspace/programs/task-54c9fb29.py",
 "content": "def transform(grid):
    # Given the single demonstration, model each outlined component as an
    # outer frame (color 2), with enclosed zero cavities colored 3.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = {(r,c) for r in range(h) for c in range(w) if grid[r][c] == 1}
    seen=set()
    from collections import deque
    for p in ones:
        if p in seen: continue
        q=[p]; seen.add(p); comp=[]
        for r,c in q:
            comp.append((r,c))
            for a,b in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if (a,b) in ones and (a,b) not in seen: seen.add((a,b)); q.append((a,b))
        # Objects matching the demo are treated as a hollow outline: fill
        # missing perimeter cells with 2, and enclosed interior background with 3.
        r0=min(r for r,c in comp); r1=max(r for r,c in comp)
        c0=min(c for r,c in comp); c1=max(c for r,c in comp)
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if r in (r0,r1) or c in (c0,c1):
                    if out[r][c] == 0: out[r][c]=2
        # enclosed background only
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                if out[r][c] == 0: out[r][c]=3
    return out
